/**
 * 获取语言对应的 SVG 图标（同步）
 * @param language 语言标识符（不区分大小写）
 * @returns SVG 字符串，如果未匹配则返回 default
 */
export function getLanguageIconSvg(language: string): string {
  const key = language.toLowerCase();
  // 别名映射
  const aliasMap: Record<string, string> = {
    js: "javascript",
    jsx: "javascript",
    ts: "ts",
    tsx: "ts",
    py: "python",
    cpp: "cpp",
    csharp: "csharp",
    mssql: "sqlserver",
    sh: "bash",
    shell: "bash",
    yml: "yaml",
    dockerfile: "docker",
  };
  const actualKey = aliasMap[key] || key;
  return languageSvgMap[actualKey] || languageSvgMap.default;
}
